{"concept":"An immersive, electrifying Plumber HQ and Omnitrix-powered carnival theme park where every video card transforms into an alien containment vault and the header pulses with green energy rings.","fingerprint":"Orbitron neon green hexagonal alien grid","id":"38745f93682d","name":"Omnitrix Alien Carnival","dark":true,"bg":"#020b05","surface":"#161f19","surface2":"#29312b","fg":"#e2ffe8","ink":"#00ff55","accent":"#00ff55","remapSurfaces":false,"customCss":"@import url('https://fonts.googleapis.com/css2?family=Orbitron:wght@500;700;900&family=Rajdhani:wght@600;700&display=swap');

:root {
 --omni-green: #00ff55;
 --omni-glow: rgba(0, 255, 85, 0.45);
 --omni-dark: #020b05;
 --omni-plate: rgba(13, 34, 18, 0.82);
 --omni-border: #1ef36c;
 --m-rx: 0deg;
 --m-ry: 0deg;
}

* {
 font-family: 'Rajdhani', sans-serif !important;
 -webkit-font-smoothing: antialiased;
}

h1, h2, h3, .media-item-headline, .title {
 font-family: 'Orbitron', sans-serif !important;
 letter-spacing: 0.08em !important;
 text-transform: uppercase !important;
 color: #e2ffe8 !important;
 text-shadow: 0 0 8px rgba(0, 255, 85, 0.6) !important;
}

html, body {
 background-color: var(--omni-dark) !important;
 color: #e2ffe8 !important;
 overflow-x: hidden !important;
}

/* Clean YouTube chrome elements */
#header-bar, ytm-mobile-topbar-renderer {
 background: linear-gradient(180deg, #020b05 0%, rgba(2,11,5,0.75) 80%, transparent 100%) !important;
 border-bottom: 2px solid var(--omni-green) !important;
 box-shadow: 0 4px 20px rgba(0,255,85,0.3) !important;
}

/* Feed & container rules */
lazy-list, ytm-section-list-renderer, [data-mydes="grid"] {
 background: transparent !important;
 display: grid !important;
 grid-template-columns: repeat(auto-fit, minmax(min(100%, 320px), 1fr)) !important;
 gap: 20px !important;
 padding: 14px !important;
 box-sizing: border-box !important;
}

/* Pod Card Styling */
ytm-video-with-context-renderer.item.adaptive-feed-item, [data-mydes="card"] {
 background: transparent !important;
 margin-bottom: 12px !important;
 perspective: 1000px !important;
}

ytm-media-item {
 position: relative !important;
 display: flex !important;
 flex-direction: column !important;
 background: var(--omni-plate) !important;
 border: 1px solid var(--omni-border) !important;
 clip-path: polygon(14px 0, 100% 0, 100% calc(100% - 14px), calc(100% - 14px) 100%, 0 100%, 0 14px) !important;
 box-shadow: inset 0 0 15px rgba(0, 255, 85, 0.15), 0 8px 24px rgba(0, 0, 0, 0.6) !important;
 border-radius: 0 !important;
 padding: 10px !important;
 overflow: hidden !important;
 transition: transform 0.25s cubic-bezier(0.2, 0.8, 0.2, 1), box-shadow 0.25s ease !important;
 transform: perspective(900px) rotateX(var(--m-rx, 0deg)) rotateY(var(--m-ry, 0deg)) !important;
}

ytm-video-with-context-renderer:nth-child(even) ytm-media-item {
 border-color: #00cca3 !important;
 box-shadow: inset 0 0 16px rgba(0, 204, 163, 0.2), 0 8px 24px rgba(0, 0, 0, 0.6) !important;
}

ytm-media-item:active, ytm-media-item:hover {
 transform: perspective(900px) scale(1.02) rotateX(calc(var(--m-rx, 0deg) * 1.5)) rotateY(calc(var(--m-ry, 0deg) * 1.5)) !important;
 box-shadow: inset 0 0 25px rgba(0, 255, 85, 0.35), 0 12px 30px rgba(0, 255, 85, 0.4) !important;
}

/* Holographic thumbnail framing */
ytm-media-item .media-item-thumbnail-container, ytm-thumbnail-cover {
 border-radius: 4px !important;
 position: relative !important;
 overflow: hidden !important;
 border: 1px solid rgba(0, 255, 85, 0.5) !important;
}

.media-item-thumbnail-container::after {
 content: '' !important;
 position: absolute !important;
 top: 0; left: 0; right: 0; bottom: 0 !important;
 background: linear-gradient(180deg, rgba(0, 255, 85, 0.12) 0%, transparent 40%, rgba(0, 255, 85, 0.08) 100%) !important;
 pointer-events: none !important;
}

/* Text & Details metadata */
div.media-item-details {
 width: 100% !important;
 padding: 10px 4px 4px 4px !important;
 box-sizing: border-box !important;
}

.media-item-metadata, .subhead, .compact-media-item-stats {
 color: #79c98d !important;
 font-size: 0.85rem !important;
 letter-spacing: 0.05em !important;
 text-transform: uppercase !important;
}

/* Injected Ornaments Styling */
.omni-card-bracket {
 position: absolute;
 top: 4px;
 right: 6px;
 width: 32px;
 height: 32px;
 pointer-events: none;
 z-index: 5;
 opacity: 0.85;
}

.omni-dna-track {
 position: absolute;
 bottom: 0;
 left: 0;
 width: 100%;
 height: 3px;
 background: repeating-linear-gradient(90deg, #00ff55 0px, #00ff55 6px, transparent 6px, transparent 12px);
 animation: dnaFlow 1.8s linear infinite;
}

@keyframes dnaFlow {
 0% { background-position: 0 0; }
 100% { background-position: 24px 0; }
}

.omnitrix-header-core {
 display: flex;
 align-items: center;
 justify-content: center;
 padding: 8px 12px;
 margin-bottom: 8px;
 background: radial-gradient(circle, rgba(0, 255, 85, 0.2) 0%, transparent 70%);
}

.omnitrix-core-svg {
 width: 54px;
 height: 54px;
 animation: dialSpin 12s linear infinite, corePulse 2.5s ease-in-out infinite alternate;
 filter: drop-shadow(0 0 10px #00ff55);
}

@keyframes dialSpin {
 0% { transform: rotate(0deg); }
 100% { transform: rotate(360deg); }
}

@keyframes corePulse {
 0% { filter: drop-shadow(0 0 6px #00ff55); }
 100% { filter: drop-shadow(0 0 18px #00ff88); }
}

/* Custom scrollbar */
::-webkit-scrollbar {
 width: 6px;
}
::-webkit-scrollbar-track {
 background: #020b05;
}
::-webkit-scrollbar-thumb {
 background: #00ff55;
 border-radius: 3px;
}","backdropHtml":"<svg id="omnitrix-stage" width="100%" height="100%" style="position:fixed;top:0;left:0;width:100vw;height:100vh;pointer-events:none;z-index:0;opacity:0.42;" xmlns="http://www.w3.org/2000/svg">
 <defs>
 <radialGradient id="bgOmni" cx="50%" cy="50%" r="50%">
 <stop offset="0%" stop-color="#00ff55" stop-opacity="0.3"/>
 <stop offset="60%" stop-color="#063312" stop-opacity="0.1"/>
 <stop offset="100%" stop-color="#020b05" stop-opacity="0.85"/>
 </radialGradient>
 <pattern id="omniGrid" width="40" height="40" patternUnits="userSpaceOnUse">
 <path d="M 40 0 L 0 0 0 40" fill="none" stroke="#00ff55" stroke-width="0.6" stroke-opacity="0.18"/>
 <circle cx="0" cy="0" r="1" fill="#00ff55" fill-opacity="0.4"/>
 </pattern>
 </defs>
 <rect width="100%" height="100%" fill="#020b05"/>
 <rect width="100%" height="100%" fill="url(#omniGrid)"/>
 <!-- Glowing Omnitrix Alien Rings -->
 <g transform="translate(205, 440)">
 <circle r="180" fill="url(#bgOmni)"/>
 <circle r="220" fill="none" stroke="#00ff55" stroke-width="2" stroke-dasharray="14 8" opacity="0.4">
 <animateTransform attributeName="transform" type="rotate" from="0" to="360" dur="30s" repeatCount="indefinite"/>
 </circle>
 <circle r="160" fill="none" stroke="#1ef36c" stroke-width="1.5" stroke-dasharray="30 15 10 15" opacity="0.5">
 <animateTransform attributeName="transform" type="rotate" from="360" to="0" dur="20s" repeatCount="indefinite"/>
 </circle>
 <!-- Hourglass shape -->
 <polygon points="-70,-110 70,-110 0,0" fill="#00ff55" opacity="0.22"/>
 <polygon points="-70,110 70,110 0,0" fill="#00ff55" opacity="0.22"/>
 </g>
</svg>","customJs":"(() => {
 if (window.MydesBridge) {
 MydesBridge.enable3DTilt(10);

 // Top bar Omnitrix dial injector
 const omniHeader = `
 <div class="omnitrix-header-core">
 <svg class="omnitrix-core-svg" viewBox="0 0 100 100">
 <circle cx="50" cy="50" r="46" fill="#07190d" stroke="#00ff55" stroke-width="4"/>
 <circle cx="50" cy="50" r="38" fill="#000" stroke="#333" stroke-width="2" stroke-dasharray="6 4"/>
 <polygon points="25,20 75,20 50,50" fill="#00ff55"/>
 <polygon points="25,80 75,80 50,50" fill="#00ff55"/>
 <circle cx="50" cy="50" r="10" fill="#e2ffe8" filter="drop-shadow(0 0 5px #00ff55)"/>
 </svg>
 </div>
 `;
 MydesBridge.injectOrnament('ytm-mobile-topbar-renderer', omniHeader, 'prepend');

 // Corner targeting reticle & DNA bar for each card
 const cardOrnament = `
 <div class="omni-card-bracket">
 <svg viewBox="0 0 40 40" width="100%" height="100%">
 <path d="M10,2 L38,2 L38,30" fill="none" stroke="#00ff55" stroke-width="3" stroke-linecap="round"/>
 <circle cx="35" cy="5" r="2.5" fill="#00ff55"/>
 </svg>
 </div>
 <div class="omni-dna-track"></div>
 `;
 MydesBridge.decorateUnits('ytm-media-item', () => cardOrnament);
 }
})();"}

{"concept":"An action-thriller Bollywood cinematic interface inspired by Salman Khan's iconic turquoise turquoise-stone Firoza bracelet, midnight highway asphalt, and rugged cinematic bravado.","fingerprint":"Rajdhani cinematic turquoise metallic angular grid","id":"1f2f79875370","name":"Bhai Cinematic Universe","dark":true,"bg":"#0a0c10","surface":"#1e1f23","surface2":"#303135","fg":"#e6f1f5","ink":"#a0b2c6","accent":"#00d2ff","remapSurfaces":false,"customCss":"@import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@700;900&family=Rajdhani:wght@600;700&display=swap');

:root {
 --firoza-blue: #00d2ff;
 --firoza-glow: rgba(0, 210, 255, 0.45);
 --silver-metal: #c2d1db;
 --curb-yellow: #f5a623;
}

body, html, #app, ytm-app, .ytmDrawerLayoutContainerDrawerLayout {
 background: transparent !important;
 color: #e6f1f5 !important;
 font-family: 'Rajdhani', sans-serif !important;
}

lazy-list, #app-body, .adaptive-feed, div.ytGridShelfViewModelGridShelfRow.item {
 background: transparent !important;
}

/* Top Bar Cinematic Re-skin */
ytm-pivot-bar-renderer, ytm-mobile-topbar-renderer {
 background: linear-gradient(180deg, rgba(8, 11, 15, 0.96) 0%, rgba(13, 17, 23, 0.85) 100%) !important;
 border-bottom: 2px solid var(--firoza-blue) !important;
 box-shadow: 0 4px 20px var(--firoza-glow) !important;
 backdrop-filter: blur(12px) !important;
}

/* Video Feeds & Grids */
lazy-list {
 display: grid !important;
 grid-template-columns: repeat(auto-fit, minmax(min(100%, 185px), 1fr)) !important;
 gap: 16px !important;
 padding: 12px !important;
 box-sizing: border-box !important;
}

/* Composite Card Silhouettes & 3D Tilt */
ytm-video-with-context-renderer.item.adaptive-feed-item,
div.ytGridShelfViewModelGridShelfItem {
 width: 100% !important;
 max-width: 100% !important;
 margin: 0 !important;
 padding: 8px !important;
 box-sizing: border-box !important;
 background: var(--surface) !important;
 border-radius: 6px !important;
 clip-path: polygon(0% 0%, 92% 0%, 100% 8%, 100% 100%, 8% 100%, 0% 92%) !important;
 border: 1px solid rgba(0, 210, 255, 0.3) !important;
 box-shadow: 0 8px 24px rgba(0, 0, 0, 0.8), inset 0 0 15px rgba(0, 210, 255, 0.08) !important;
 transform: perspective(900px) rotateX(var(--m-rx, 0deg)) rotateY(var(--m-ry, 0deg)) !important;
 transition: border-color 0.25s ease, box-shadow 0.25s ease !important;
 position: relative !important;
 overflow: hidden !important;
}

ytm-video-with-context-renderer.item.adaptive-feed-item:nth-child(even) {
 border-color: rgba(194, 209, 219, 0.4) !important;
}

/* Card Inner Flex Column Reflow */
ytm-media-item.big-shorts-singleton {
 display: flex !important;
 flex-direction: column !important;
 width: 100% !important;
}

a.media-item-thumbnail-container, .shortsLockupViewModelHostEndpoint {
 width: 100% !important;
 border-radius: 4px !important;
 overflow: hidden !important;
 border: 1px solid rgba(255, 255, 255, 0.1) !important;
}

.media-item-details, .shortsLockupViewModelHostOutsideMetadata {
 width: 100% !important;
 padding-top: 8px !important;
}

/* Typography & Text */
h3, .media-item-headline, .shortsLockupViewModelHostOutsideMetadataTitle {
 font-family: 'Cinzel', serif !important;
 font-weight: 700 !important;
 font-size: 13px !important;
 letter-spacing: 0.5px !important;
 color: #ffffff !important;
 text-shadow: 0 1px 4px rgba(0, 0, 0, 0.9) !important;
 -webkit-line-clamp: 2 !important;
 white-space: normal !important;
}

.media-channel, .ytm-badge-and-byline-renderer, .subhead {
 font-family: 'Rajdhani', sans-serif !important;
 font-weight: 600 !important;
 color: #7ce3ff !important;
 text-transform: uppercase !important;
 letter-spacing: 1px !important;
}

/* Ornament placement */
.bhai-card-ornament {
 position: absolute;
 bottom: 0;
 right: 0;
 pointer-events: none;
 opacity: 0.35;
 z-index: 2;
 mix-blend-mode: screen;
}

.firoza-header-stage {
 display: flex;
 align-items: center;
 justify-content: center;
 padding: 6px 0;
 background: radial-gradient(circle, rgba(0, 210, 255, 0.2) 0%, transparent 70%);
}

@keyframes pulseBracelet {
 0% { transform: scale(1) rotate(0deg); filter: drop-shadow(0 0 6px rgba(0,210,255,0.7)); }
 50% { transform: scale(1.04) rotate(180deg); filter: drop-shadow(0 0 16px rgba(0,210,255,1)); }
 100% { transform: scale(1) rotate(360deg); filter: drop-shadow(0 0 6px rgba(0,210,255,0.7)); }
}

.firoza-ring {
 animation: pulseBracelet 18s linear infinite;
 transform-origin: center;
}
/* review patch */
h3, .media-item-headline, .shortsLockupViewModelHostOutsideMetadataTitle { white-space: normal !important; word-break: break-word !important; width: 100% !important; max-width: 100% !important; display: block !important; -webkit-line-clamp: 2 !important; -webkit-box-orient: vertical !important; overflow: hidden !important; } lazy-list { grid-template-columns: repeat(auto-fit, minmax(min(100%, 140px), 1fr)) !important; }","backdropHtml":"<div style="position:fixed;top:0;left:0;width:100vw;height:100vh;pointer-events:none;z-index:-1;background:#080b0e;overflow:hidden;"><svg width="100%" height="100%" xmlns="http://www.w3.org/2000/svg" opacity="0.55"><defs><pattern id="asphalt" width="120" height="120" patternUnits="userSpaceOnUse"><line x1="0" y1="20" x2="120" y2="20" stroke="#151b24" stroke-width="1.5" stroke-dasharray="10 15"/><line x1="0" y1="60" x2="120" y2="60" stroke="#1c2533" stroke-width="2" stroke-dasharray="30 20"/><line x1="0" y1="100" x2="120" y2="100" stroke="#151b24" stroke-width="1.5" stroke-dasharray="5 25"/></pattern><linearGradient id="firozaGlow" x1="0%" y1="0%" x2="100%" y2="100%"><stop offset="0%" stop-color="#00d2ff" stop-opacity="0.2"/><stop offset="50%" stop-color="#005577" stop-opacity="0.05"/><stop offset="100%" stop-color="#080b0e" stop-opacity="0"/></linearGradient></defs><rect width="100%" height="100%" fill="url(#asphalt)"/><path d="M-50,150 Q180,450 450,220 T900,600" fill="none" stroke="#1c2738" stroke-width="28" opacity="0.4" stroke-dasharray="8 12"/><path d="M-30,170 Q200,470 470,240 T920,620" fill="none" stroke="#1c2738" stroke-width="28" opacity="0.4" stroke-dasharray="8 12"/><circle cx="80%" cy="20%" r="260" fill="url(#firozaGlow)"/><circle cx="15%" cy="80%" r="320" fill="url(#firozaGlow)"/><g stroke="rgba(0, 210, 255, 0.15)" stroke-width="1.5" fill="none"><path d="M40,500 L65,470 L75,485 L90,450 L100,470 L130,475 L115,510 L95,530 L60,530 Z"/><path d="M85,450 L75,420 L95,410 L100,430"/><path d="M75,420 L65,390 L85,380"/></g></svg></div>","customJs":"(function() {
 MydesBridge.enable3DTilt(14);

 var firozaAmuletSvg = '<div class="firoza-header-stage"><svg width="42" height="42" viewBox="0 0 100 100" class="firoza-ring"><circle cx="50" cy="50" r="42" fill="none" stroke="#a6b8c7" stroke-width="7" stroke-dasharray="14 6"/><rect x="34" y="34" width="32" height="32" rx="6" fill="#00d2ff" stroke="#ffffff" stroke-width="3"/><rect x="39" y="39" width="22" height="22" rx="3" fill="#00a3cc"/><circle cx="45" cy="45" r="3" fill="#ffffff" opacity="0.8"/></svg></div>';
 MydesBridge.injectOrnament('ytm-mobile-topbar-renderer', firozaAmuletSvg, 'append');

 var tyreTrackCardSvg = '<svg class="bhai-card-ornament" width="65" height="65" viewBox="0 0 100 100"><path d="M10,90 L30,70 M25,95 L45,75 M40,100 L60,80 M55,105 L75,85 M70,110 L90,90" stroke="#00d2ff" stroke-width="4" opacity="0.35" stroke-linecap="round"/><path d="M20,100 L40,80 M35,105 L55,85 M50,110 L70,90 M65,115 L85,95" stroke="#ffffff" stroke-width="2" opacity="0.2" stroke-linecap="round"/></svg>';
 MydesBridge.decorateUnits('ytm-video-with-context-renderer.item.adaptive-feed-item, div.ytGridShelfViewModelGridShelfItem', tyreTrackCardSvg);
})();"}

